insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'conclusion',1,'Eighteen indexed records report the order that Abū Bakr lead the prayer during the final illness. They come through five Companions: ʿĀʾisha (12), Abū Mūsā (3), and Ibn ʿUmar, Ibn ʿAbbās and Sālim b. ʿUbayd (1 each). Every route through ʿĀʾisha ends with her.',array['bukhari:664','bukhari:678','bukhari:682','ibnmajah:1235','ibnmajah:1234']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'conclusion',2,'Every member affirms the order itself ("murū Abā Bakr"). No member negates it.',array['bukhari:664','muslim:418f','nasai:833','tirmidhi:3672']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'conclusion',3,'The objection is worded three ways: "rajul asīf" (al-Aʿmash → Ibrāhīm → al-Aswad and Saʿd b. Ibrāhīm → ʿUrwa), "rajul raqīq" (Abū Mūsā, Ibn ʿUmar, Ibn ʿAbbās routes), and "he will not make the people hear for weeping" (Hishām b. ʿUrwa → ʿUrwa). These are classed as wording variants of one objection.',array['bukhari:712','bukhari:678','bukhari:679']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'conclusion',4,'Only ʿĀʾisha’s report via Ḥamza b. ʿAbd Allāh (Muslim 418e) states her motive: she feared people would see an ill omen in whoever first stood in his place. The rest are silent on this, which is an omission, not a contradiction.',array['muslim:418e']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'conclusion',5,'Who supported him to the mosque: Ibn ʿAbbās (Ibn Mājah 1235) names al-ʿAbbās and ʿAlī. The ʿĀʾisha reports in this set say "between two men" without naming them, so there is no conflict.',array['ibnmajah:1235','bukhari:664']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'uncertainty',1,'Muwaṭṭaʾ Mālik record 100906 (stored no. 418) could not be matched to a sunnah.com page yet. Every stored Muwaṭṭaʾ link uses the form sunnah.com/malik:N, which returns 404. It stays an unverified candidate.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'uncertainty',2,'All 18 stored numbers/links differ from the sunnah.com reference (for example Bukhārī 646 → 664, Muslim 843 → 418f, Ibn Mājah 966 → 1232).','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'uncertainty',3,'Isnad names are auto-extracted text chunks (candidates). Single-report branches show the collector’s teacher as their "common link", which is trivially true and carries no weight.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'uncertainty',4,'Riyāḍ al-Ṣāliḥīn 1670 was excluded because it is a derivative quotation.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='final-illness-abu-bakr-prayer'),'uncertainty',5,'Narrative group 17 (age at death) is a different question and is not merged. No existing narrative group covers this incident.','grok-bot') on conflict do nothing;
